'use strict';
// Additional models from the competency-to-control review.
model('composite','Composite area & perimeter',[C('w','Outer width',2,12,8),C('h','Outer height',2,10,6),C('cutw','Cut-out width',1,10,3),C('cuth','Cut-out height',1,8,2),S('view','Shape',['L-shaped rectangle','Rectangle with semicircle'])],'Split the figure into familiar shapes. Which edges belong to the outside perimeter?',s=>{let w=s.w,h=s.h,c=Math.min(s.cutw,w-1),d=Math.min(s.cuth,h-1),z=24,x=110,y=50,p,A,P;if(s.view==='L-shaped rectangle'){p=poly([[x,y],[x+(w-c)*z,y],[x+(w-c)*z,y+d*z],[x+w*z,y+d*z],[x+w*z,y+h*z],[x,y+h*z]])+line(x,y+d*z,x+(w-c)*z,y+d*z,'#bd8f41',2,'4 4');A=w*h-c*d;P=2*(w+h)}else{p=rect(x,y,w*z,h*z)+`<path d="M${x+w*z} ${y} A${h*z/2} ${h*z/2} 0 0 1 ${x+w*z} ${y+h*z} Z" fill="#e4c385" stroke="#216c58"/>`;A=w*h+Math.PI*(h/2)**2/2;P=2*w+h+Math.PI*h/2}return[svg(p+txt(300,330,s.view==='L-shaped rectangle'?`Outer ${w} × ${h}; removed ${c} × ${d}`:`Rectangle ${w} × ${h}; semicircle diameter ${h}`,18)),`Area = ${fmt(A)} square units; perimeter = ${fmt(P)} units. ${s.view==='L-shaped rectangle'?'Subtract the missing rectangle from the outer rectangle.':'Add half a circle; the shared diameter is not an outside edge.'}`]});
model('pyramid','Pyramids with different bases',[S('shape','Base',['Rectangle','Triangle','Regular pentagon','Regular hexagon']),C('a','Base length / regular side',1,10,4),C('b','Base width / triangle height',1,10,3),C('h','Perpendicular pyramid height',1,12,6)],'Compare a pyramid and a prism with the same base area and perpendicular height. Why is the ratio always one to three?',s=>{let n=s.shape==='Regular pentagon'?5:6,A=s.shape==='Rectangle'?s.a*s.b:s.shape==='Triangle'?s.a*s.b/2:n*s.a*s.a/(4*Math.tan(Math.PI/n));let points=s.shape==='Rectangle'?[[140,250],[350,300],[450,240],[250,200]]:Array.from({length:s.shape==='Triangle'?3:n},(_,i)=>[300+155*Math.cos(2*Math.PI*i/(s.shape==='Triangle'?3:n)),255+45*Math.sin(2*Math.PI*i/(s.shape==='Triangle'?3:n))]);return[svg(poly(points)+points.map(p=>line(...p,300,55)).join('')+line(300,55,300,255,'#bd8f41',3,'5 5')+txt(300,335,'Schematic; dashed segment is perpendicular height',15)),`Base area = ${fmt(A)}. Pyramid V = ⅓Bh = ${fmt(A*s.h/3)} cubic units. Matching prism V = ${fmt(A*s.h)} cubic units.`]});
model('absolute','Absolute value equations',[C('h','Center h',-8,8,2),C('k','Distance k',-2,8,3)],'Solve |x − h| = k by finding points at distance k from h. Explain what happens when k is zero or negative.',s=>{let p=line(50,190,550,190);for(let i=-16;i<=16;i+=2)p+=txt(300+i*15,230,i,13);p+=dot(300+s.h*15,190,7,'#c38b35')+txt(300+s.h*15,155,'h',20);if(s.k>=0)for(let x of new Set([s.h-s.k,s.h+s.k]))p+=dot(300+x*15,190,9)+txt(300+x*15,270,fmt(x),20);return[svg(p),`|x − (${s.h})| = ${s.k}. ${s.k<0?'No solution: distance cannot be negative.':s.k===0?'One solution: x = '+s.h:'Two solutions: x = '+(s.h-s.k)+' or x = '+(s.h+s.k)}.`]});
model('functions','Relations, domain & range',[T('pairs','Ordered pairs: x,y; x,y','1,2;2,4;3,6'),C('test','Input to inspect',-10,10,2)],'Give one input two different outputs. Is the relation still a function? Explain using the mapping.',s=>{let p=String(s.pairs).split(';').map(t=>t.split(',').map(v=>Number(v.trim()))).filter(a=>a.length===2&&a.every(Number.isFinite)).slice(0,12);if(!p.length)return['Enter pairs such as 1,2;2,4.','No valid ordered pairs.'];let xs=[...new Set(p.map(a=>a[0]))],ys=[...new Set(p.map(a=>a[1]))],fn=xs.every(x=>new Set(p.filter(a=>a[0]===x).map(a=>a[1])).size===1),Y=(i,n)=>50+i*260/Math.max(1,n-1);return[svg(p.map(([x,y])=>line(145,Y(xs.indexOf(x),xs.length),455,Y(ys.indexOf(y),ys.length),x===s.test?'#bd8f41':'#8bbca3',x===s.test?4:2)).join('')+xs.map((x,i)=>txt(110,Y(i,xs.length)+6,fmt(x),19)).join('')+ys.map((y,i)=>txt(490,Y(i,ys.length)+6,fmt(y),19)).join('')),`${fn?'Function':'Not a function'}: ${fn?'every input has exactly one output.':'at least one input has different outputs.'}<br>Domain = {${xs.map(fmt).join(', ')}}; range = {${ys.map(fmt).join(', ')}}. Outputs for ${s.test}: ${[...new Set(p.filter(a=>a[0]===s.test).map(a=>a[1]))].join(', ')||'none'}.`]});
model('sampling','Sampling & representative data',[S('method','Sample',['First row only','Every fifth learner','One from each row']),C('offset','Starting column / offset',0,4,0)],'Rows represent five classes with different travel times. Compare a convenience sample with a sample that includes every class. Which supports a claim about the whole school?',s=>{let population=Array.from({length:25},(_,i)=>5+Math.floor(i/5)*10+i%5),ids=s.method==='First row only'?[0,1,2,3,4]:s.method==='Every fifth learner'?Array.from({length:5},(_,i)=>s.offset+i*5):Array.from({length:5},(_,i)=>i*5+(s.offset+i)%5),mean=ids.reduce((a,i)=>a+population[i],0)/ids.length;return[svg(population.map((v,i)=>rect(100+i%5*80,30+Math.floor(i/5)*55,70,45,ids.includes(i)?'#ddb568':'#d7e8de')+txt(135+i%5*80,60+Math.floor(i/5)*55,v,18)).join('')),`Travel time in minutes. Population mean = 27; sample mean = ${fmt(mean)}. Gold cells are sampled. This is a deterministic demonstration, not a random survey. Discuss convenience, systematic, stratified and simple random sampling; collect actual class data separately.`]});
model('statistics','Frequency, position & variability',[T('data','Data (comma-separated)','2,3,3,5,7,8,12'),C('percentile','Percentile / decile × 10',0,100,75),N('score','Score for percentile rank',-1000,1000,7),S('view','Display',['Frequency table','Stem-and-leaf','Cumulative frequency'])],'Change one score to an outlier. Compare mean deviation, standard deviation, percentile rank and the cumulative frequencies.',s=>{let a=String(s.data).split(',').map(x=>x.trim()).filter(Boolean).map(Number).filter(Number.isFinite).sort((a,b)=>a-b).slice(0,60);if(!a.length)return['Enter numeric data.','No valid data.'];let n=a.length,mean=a.reduce((x,y)=>x+y,0)/n,mad=a.reduce((t,v)=>t+Math.abs(v-mean),0)/n,sd=Math.sqrt(a.reduce((t,v)=>t+(v-mean)**2,0)/n),q=p=>{let j=(n-1)*p,i=Math.floor(j);return a[i]+(a[Math.min(i+1,n-1)]-a[i])*(j-i)},iqr=q(.75)-q(.25),freq=[...new Set(a)].map(v=>[v,a.filter(x=>x===v).length,a.filter(x=>x<=v).length]),pic=table(['Value','Frequency','Cumulative'],freq);if(s.view==='Stem-and-leaf'){if(a.some(v=>v<0||!Number.isInteger(v)))pic='Stem-and-leaf view uses nonnegative whole numbers.';else{let stems=[...new Set(a.map(v=>Math.floor(v/10)))];pic=table(['Stem','Leaves (key: 1 | 2 = 12)'],stems.map(v=>[v,a.filter(x=>Math.floor(x/10)===v).map(x=>x%10).join(' ')]))}}if(s.view==='Cumulative frequency'){let lo=a[0],hi=a.at(-1),X=v=>60+(v-lo)/(hi-lo||1)*480,Y=v=>300-v/n*250;pic=svg(line(60,300,550,300)+freq.map(([v,f,c],i)=>dot(X(v),Y(c))+txt(X(v),330,fmt(v),12)+txt(X(v),Y(c)-12,c,14)+(i?line(X(freq[i-1][0]),Y(freq[i-1][2]),X(v),Y(c)):'' )).join('')+txt(300,25,'Cumulative frequency polygon (individual values)',16))}return[`<div class="canvas-column">${pic}</div>`,`n = ${n}; mean deviation about mean = ${fmt(mad)}; population SD = ${fmt(sd)}.<br>P${s.percentile} = ${fmt(q(s.percentile/100))}; IQR = ${fmt(iqr)}; outliers (1.5 × IQR rule): ${a.filter(v=>v<q(.25)-1.5*iqr||v>q(.75)+1.5*iqr).join(', ')||'none'}.<br>Percentile rank of ${s.score} = ${fmt(100*(a.filter(v=>v<s.score).length+.5*a.filter(v=>v===s.score).length)/n)}%. Rank uses below + half of ties; percentiles use linear interpolation. State the convention when comparing textbook answers.`]});
model('scientific','Scientific notation operations',[N('a','First coefficient',-9.99,9.99,3,.01),C('p','First exponent',-12,12,4),N('b','Second coefficient',-9.99,9.99,2,.01),C('q','Second exponent',-12,12,3),S('op','Operation',['+','−','×','÷'])],'Predict the exponent before multiplying. Why do addition and subtraction require equal powers of ten?',s=>{let a=s.a*10**s.p,b=s.b*10**s.q,r=s.op==='+'?a+b:s.op==='−'?a-b:s.op==='×'?a*b:b?a/b:NaN;let e=r&&Number.isFinite(r)?Math.floor(Math.log10(Math.abs(r))):0,m=r/10**e;return[`<div class="big-math">(${s.a} × 10<sup>${s.p}</sup>) ${s.op}<br>(${s.b} × 10<sup>${s.q}</sup>)</div>`,Number.isFinite(r)?`Result: ${fmt(m)} × 10<sup>${e}</sup>${r===0?' (zero has no unique normalized exponent)':''}. ${s.op==='×'?'Multiply coefficients and add exponents.':s.op==='÷'?'Divide coefficients and subtract exponents.':'Align exponents before combining coefficients.'}`:'Undefined: division by zero.']});
model('monomials','Monomial operations',[C('a','Coefficient a',-10,10,3),C('p','Power p',0,6,2),C('b','Coefficient b',-10,10,2),C('q','Power q',0,6,3),S('op','Operation',['Add','Subtract','Multiply','Divide'])],'Choose like terms, then unlike terms. When can coefficients be combined? Contrast addition with multiplication.',s=>{let r=s.op==='Add'||s.op==='Subtract'?(s.p===s.q?`${s.a+(s.op==='Add'?s.b:-s.b)}x<sup>${s.p}</sup>`:`${s.a}x<sup>${s.p}</sup> ${s.op==='Add'?'+':'−'} (${s.b}x<sup>${s.q}</sup>): unlike powers cannot be combined`):s.op==='Multiply'?`${s.a*s.b}x<sup>${s.p+s.q}</sup>`:s.b===0?'Undefined: zero divisor':`${frac(s.a,s.b)}x<sup>${s.p-s.q}</sup>${s.q>0?' (x ≠ 0)':''}`;return[`<div class="big-math">${s.a}x<sup>${s.p}</sup> &nbsp; and &nbsp; ${s.b}x<sup>${s.q}</sup></div>`,`${s.op}: ${r}.`]});
model('radicals','Radical simplification & equations',[C('n','Positive radicand n',1,200,72),C('a','Equation offset a',-10,10,4),C('b','Equation right side b',-5,12,3)],'Simplify √n by finding a square factor. For √(x + a) = b, square both sides and check the candidate in the original equation.',s=>{let k=1;for(let i=1;i*i<=s.n;i++)if(s.n%(i*i)===0)k=i;let r=s.n/(k*k),x=s.b*s.b-s.a;return[`<div class="big-math">√${s.n} = ${r===1?k:(k===1?'':k)+'√'+r}<p>√(x + (${s.a})) = ${s.b}</p></div>`,`Square factor: ${k*k}. Rationalize 1/√${s.n} = √${s.n}/${s.n}.<br>Candidate x = b² − a = ${x}. ${s.b<0?'Rejected: a principal square root cannot be negative.':'Check: √('+fmt(x+s.a)+') = '+s.b+'; valid solution.'}`]});
model('trianglecheck','Triangle inequality & classification',[C('a','Side a',1,15,3),C('b','Side b',1,15,4),C('c','Side c',1,15,5)],'Find three positive lengths that cannot form a triangle. Then compare the square of the longest side with the sum of the other two squares.',s=>{let sides=[s.a,s.b,s.c].sort((a,b)=>a-b),[a,b,c]=sides,valid=a+b>c,delta=c*c-a*a-b*b,p=txt(300,70,`${a} + ${b} ${valid?'>':'≤'} ${c}`,30);if(valid){let x=(s.a*s.a+s.c*s.c-s.b*s.b)/(2*s.c),h=Math.sqrt(Math.max(0,s.a*s.a-x*x)),z=22;p+=poly([[100,300],[100+s.c*z,300],[100+x*z,300-h*z]])}else p+=txt(300,180,'These lengths cannot close a triangle.',21);return[svg(p),valid?`${s.a===s.b&&s.b===s.c?'Equilateral':s.a===s.b||s.b===s.c||s.a===s.c?'Isosceles':'Scalene'}; ${delta===0?'right':delta>0?'obtuse':'acute'} triangle. Longest-side square = ${c*c}; other squares sum = ${a*a+b*b}.`:'No triangle: the sum of the two shorter sides must exceed the longest side.']});
model('blocks','Tens, ones & regrouping',[C('a','First number',0,99,27),C('b','Second number',0,99,15),S('op','Operation',['Build','Add','Subtract'])],'Trade ten ones for one ten. Does the total change? Explain the trade when adding or subtracting.',s=>{let n=s.op==='Build'?s.a:s.op==='Add'?s.a+s.b:s.a-s.b;if(n<0)return[svg(txt(300,180,'Result is below zero.',26)),`${s.a} − ${s.b} = ${n}. Use the number line for negative results.`];let tens=Math.floor(n/10),ones=n%10,p='';for(let i=0;i<tens;i++){let x=50+(i%10)*45,y=30+Math.floor(i/10)*130;for(let j=0;j<10;j++)p+=rect(x,y+j*10,25,9,'#85bba2')}for(let i=0;i<ones;i++)p+=rect(60+i*45,310,25,25,'#d8ae60');let regroup=s.op==='Add'?(s.a%10+s.b%10>=10?'Trade 10 ones for 1 ten.':'No regrouping of ones needed.'):s.op==='Subtract'?(s.a%10<s.b%10?'Trade 1 ten for 10 ones before taking away.':'No regrouping of ones needed.'):'Each rod contains 10 ones.';return[svg(p),`${s.op==='Build'?s.a:s.a+(s.op==='Add'?' + ':' − ')+s.b+' = '+n}: ${tens} tens and ${ones} ones. ${regroup}`]});
